Algoritmo Mochila
  Definir libros, cuadernos Como Entero;
  Definir nombre Como Cadena <- "Leo";
  libros <- 3;
  cuadernos <- libros * 2;
  Escribir nombre, " lleva ", libros, " libros y ", cuadernos, " cuadernos";
FinAlgoritmo

Algoritmo Varios
  Definir a, b Como Entero <- 0;
  Escribir a;
FinAlgoritmo

Algoritmo Repetido
  Definir x Como Entero <- 1;
  Definir x Como Entero <- 2;
  Escribir x;
FinAlgoritmo
